// BTI DWG Validation Logic
const data = $input.all();
const validationResults = [];

for (const item of data) {
  const rowData = item.json;

  // Validation checks for BTI requirements
  const checks = {
    layer_exists: rowData.Layer !== undefined && rowData.Layer !== '',
    entity_type_valid: rowData.EntityType !== undefined,
    area_calculated: rowData.Area !== undefined && rowData.Area > 0,
    perimeter_calculated: rowData.Perimeter !== undefined && rowData.Perimeter > 0,
    coordinates_valid: rowData.X !== undefined && rowData.Y !== undefined
  };

  // Count issues
  const issues = [];
  if (!checks.layer_exists) issues.push('Missing layer information');
  if (!checks.entity_type_valid) issues.push('Invalid entity type');
  if (!checks.area_calculated) issues.push('Area not calculated');
  if (!checks.perimeter_calculated) issues.push('Perimeter not calculated');
  if (!checks.coordinates_valid) issues.push('Missing coordinates');

  validationResults.push({
    json: {
      entity_id: rowData.Handle || rowData.ElementId || 'unknown',
      layer: rowData.Layer || 'unknown',
      entity_type: rowData.EntityType || 'unknown',
      checks: checks,
      issues: issues,
      status: issues.length === 0 ? 'PASS' : 'FAIL',
      issues_count: issues.length
    }
  });
}

return validationResults;

// Generate Summary Statistics
const items = $input.all();
const summary = {
  total_entities: items.length,
  passed: items.filter(i => i.json.status === 'PASS').length,
  failed: items.filter(i => i.json.status === 'FAIL').length,
  validation_timestamp: new Date().toISOString(),
  issues_by_type: {}
};

// Count issues by type
for (const item of items) {
  if (item.json.issues && item.json.issues.length > 0) {
    for (const issue of item.json.issues) {
      summary.issues_by_type[issue] = (summary.issues_by_type[issue] || 0) + 1;
    }
  }
}

summary.pass_rate = ((summary.passed / summary.total_entities) * 100).toFixed(2) + '%';

return [{ json: summary }];
